    }

    // Test subclass to override envelope creation and OM mapping to simplify testing
    public static class TestNFeConsultaProtocolo4Stub extends NFeConsultaProtocolo4Stub {
        public TestNFeConsultaProtocolo4Stub() throws AxisFault {
            super("https://nfe.sefaz.ms.gov.br/ws/NFeConsultaProtocolo4");
        }

        @Override
