                                          NfeDadosMsg data,
                                          javax.xml.namespace.QName nfeConsultaQName,
                                          javax.xml.namespace.QName dadosMsgQName) {
            // Return a mock envelope to avoid real SOAP construction
            return mock(SOAPEnvelope.class);
        }

        @Override
        protected Object fromOM(OMElement omElement, Class<?> expectedClass) {
            if (expectedClass == NfeResultMsg.class) {
                return new NfeResultMsg();
            } else if (expectedClass == String.class) {
                return "fault message";
            }
            return null;
        }
    }

    @Test
    public void testNfeConsultaNF_success() throws Exception {
        TestNFeConsultaProtocolo4Stub stub = new TestNFeConsultaProtocolo4Stub();

