        when(returnMsgCtx.getEnvelope()).thenReturn(returnEnv);
        when(returnEnv.getBody()).thenReturn(body);
        when(body.getFirstElement()).thenReturn(firstElement);

        // After execute, ensure it doesn't throw and returns a NfeResultMsg via fromOM override
        doNothing().when(operationClient).execute(true);

        // Wire mocks into the stub instance
