        faultNameMapField.setAccessible(true);
        Map faultNameMap = (Map) faultNameMapField.get(stub);

        Field faultClassMapField = NFeConsultaProtocolo4Stub.class.getDeclaredField("faultExceptionClassNameMap");
        faultClassMapField.setAccessible(true);
        Map faultClassMap = (Map) faultClassMapField.get(stub);

        Field faultMsgMapField = NFeConsultaProtocolo4Stub.class.getDeclaredField("faultMessageMap");
        faultMsgMapField.setAccessible(true);
        Map faultMsgMap = (Map) faultMsgMapField.get(stub);

        QName faultQName = new QName("http://example.org", "SomeFault");
        Object key = new FMK(faultQName, "nfeConsultaNF"); // using FaultMapKey

        // Simple fault exception class defined in test
        class MyFaultException extends java.lang.Exception {
            public MyFaultException(String msg) { super(msg); }
            public void setFaultMessage(String msg) {}
        }

        String exceptionClassName = MyFaultException.class.getName();

        faultNameMap.put(key, exceptionClassName);
        faultClassMap.put(key, exceptionClassName);
        faultMsgMap.put(key, String.class.getName());

        // Prepare mocks
        ServiceClient serviceClient = mock(ServiceClient.class);
        OperationClient operationClient = mock(OperationClient.class);
        AxisOperation axisOp = mock(AxisOperation.class);

        when(axisOp.getName()).thenReturn("nfeConsultaNF");
        when(serviceClient.createClient(anyString())).thenReturn(operationClient);
        // Exception path: opClient.execute(true) throws AxisFault with detail containing faultElt
        AxisFault axisFault = new AxisFault("Fault occurred");
        OMElement faultElt = mock(OMElement.class);
        when(faultElt.getQName()).thenReturn(faultQName);
        axisFault.setDetail(faultElt);
        doThrow(axisFault).when(operationClient).execute(true);

        // Build return path for after catch (not reached since exception is thrown)
        // Ensure getMessageContext path won't be used after fault is thrown
        when(operationClient.getOptions()).thenReturn(mock(org.apache.axis2.client.Options.class));

        // Wire mocks into the stub
        setField(stub, "_serviceClient", serviceClient);
        setField(stub, "_operations", new AxisOperation[]{axisOp});

        // Execute and verify RemoteException is thrown with cause of MyFaultException
        try {
            stub.nfeConsultaNF(null);
            fail("Expected RemoteException to be thrown");
        } catch (java.rmi.RemoteException re) {
            assertNotNull("RemoteException should have a cause", re.getCause());
            assertTrue("Cause should be MyFaultException", re.getCause().getClass().getName().equals("NfeConsultaNFTests$1MyFaultException"));
        }
    }
}

